import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c3_out_act_k16.npy')); b=-11.9175
torch.manual_seed(5); N=8192
xi=torch.randn(N,2); c=torch.rand(N)
a0=np.load('sim_a0.npy'); tgt=np.load('sim_tgt.npy'); cn=c.numpy()
def run(delta=None, thr=0.0, klo=8, khi=20):
    x=xi.clone(); fired=torch.zeros(N)
    with torch.no_grad():
        for k in range(20):
            t=torch.full((N,),1-k/20)
            v,a=net.velocity(x,t,c,('out_act',),count=False)
            if delta is not None and klo<=k<khi:
                s=a['out_act']@w+b
                m=(s>thr).float(); fired+=m
                v=v+m[:,None]*delta
            x=x-v/20
    return x.numpy(), fired.numpy()
A0=torch.tensor(a0)
def evals(a1):
    D=torch.cdist(torch.tensor(a1),A0); D[torch.tensor(np.abs(cn[:,None]-cn[None,:])>0.04)]=1e9
    dm,j=D.min(1); j=j.numpy()
    remain=(tgt[j]&tgt).sum()/tgt.sum()
    newbad=(tgt[j]&~tgt).mean()
    atyp=(dm.numpy()>0.3)[tgt].mean()
    drift=(np.linalg.norm(a1-a0,axis=1)>0.3)[~tgt].mean()
    return round(remain,3),round(newbad,4),round(atyp,3),round(drift,4)
